var pbp = BasePoint.GetProjectBasePoint(doc);
var sp = BasePoint.GetSurveyPoint(doc);
var loc = doc.ActiveProjectLocation;
var pos = loc.GetProjectPosition(XYZ.Zero);
Func<XYZ, object> m = p => new { x = Math.Round(p.X*304.8,1), y = Math.Round(p.Y*304.8,1), z = Math.Round(p.Z*304.8,1) };
Func<XYZ, object> sh = p => { var t = loc.GetTotalTransform().OfPoint(p); return new { E = Math.Round(t.X*0.3048,3), N = Math.Round(t.Y*0.3048,3), Z = Math.Round(t.Z*0.3048,3) }; };
var sites = new FilteredElementCollector(doc).OfClass(typeof(ProjectLocation)).Cast<ProjectLocation>().Select(l => l.Name).ToList();
var levels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation)
  .Select(l => new { l.Name, elevM = Math.Round(l.Elevation*0.3048,3) }).ToList();
var ws = new FilteredWorksetCollector(doc).OfKind(WorksetKind.UserWorkset).Select(w => w.Name).ToList();
var links = new FilteredElementCollector(doc).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>().ToList();
int sharedPlaced = 0; 
var gridsPinned = new FilteredElementCollector(doc).OfClass(typeof(Grid)).Count(g => g.Pinned);
var gridsTotal = new FilteredElementCollector(doc).OfClass(typeof(Grid)).Count();
return new {
  pbpInternal = m(pbp.Position), pbpShared = sh(pbp.Position), pbpPinned = pbp.Pinned,
  spInternal = m(sp.Position), spShared = sh(sp.Position), spPinned = sp.Pinned,
  activeSite = loc.Name, sites, angleToTrueNorthDeg = Math.Round(pos.Angle*180/Math.PI,4), ewAtOrigin = Math.Round(pos.EastWest*0.3048,3), nsAtOrigin = Math.Round(pos.NorthSouth*0.3048,3), elevAtOrigin = Math.Round(pos.Elevation*0.3048,3),
  levels, worksets = ws, gridsPinned, gridsTotal };
